package com.mavric.health.persistence.sqlserver;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Executor/manager doubles do not prove ledger sums, payment semantics or BILLING links on SQL Server. */
public class SqlServerPortalBalanceStoreTest {
 public static final String ACTOR="aa000000-0000-4000-8000-000000000001",TENANT="bb000000-0000-4000-8000-000000000001",PATIENT="cc000000-0000-4000-8000-000000000001",OTHER="dd000000-0000-4000-8000-000000000001";
 public static class Fixture {
  public final SqlServerExecutor executor=mock(SqlServerExecutor.class);public final ModelTransactionManager manager=new ModelTransactionManager();public final SqlServerPortalBalanceStore store=new SqlServerPortalBalanceStore(executor,manager);public final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/portal/balance");public Actor actor;public long amount;public final List<List<Object>> args=new ArrayList<>();public final List<SqlServerContext> contexts=new ArrayList<>();public final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();
  public Fixture(){actor("PAC");when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());assertEquals(SqlServerProcedure.PORTAL_BALANCE,inv.getArgument(0));var c=inv.<SqlServerContext>getArgument(1);assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(ACTOR,c.actorId());assertEquals(TENANT,c.tenantId());assertEquals("a".repeat(64),c.tokenHash());contexts.add(c);args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));manager.events.add("sp:PORTAL_BALANCE");return results.isEmpty()?result(Map.of("balanceMinor",amount,"currency","PEN")):results.removeFirst();});}
  public void actor(String role){actor=new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of(role),"a".repeat(64));request.setAttribute("health.actor",actor);request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of("PORTAL","FINANCE")));request.setAttribute("health.requestId",OTHER);}
 }
 static SqlServerExecutor.Result result(Map<String,Object> row){return new SqlServerExecutor.Result(List.of(List.of(row)),List.of());}
 final Fixture f=new Fixture();
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable r){var e=assertThrows(ApiException.class,r::run);assertEquals(500,e.status);assertEquals("DATABASE_ERROR",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}
 @Test void exactSingleSpBindRequestAndTwoFieldImmutableProjection(){f.results.add(result(Map.of("balanceMinor",-71L,"currency","PEN","passwordHash","private-canary","tenantId",OTHER)));TraceContext.REQUEST.set(new MockHttpServletRequest());var result=f.store.balance(f.request,PATIENT);assertEquals(Map.of("balanceMinor",-71L,"currency","PEN"),result);assertEquals(List.of(PATIENT),f.args.getFirst());assertEquals(List.of("PAC"),f.contexts.getFirst().roles());assertEquals(List.of("begin:0","sp:PORTAL_BALANCE","commit"),f.manager.events);assertThrows(UnsupportedOperationException.class,result::clear);assertFalse(result.toString().contains("canary"));}
 @Test void bigintNegativeZeroAndExtremesArePreservedWithoutJavaComputation(){for(long amount:new long[]{Long.MIN_VALUE,-100L,0L,100L,Long.MAX_VALUE}){f.amount=amount;var output=f.store.balance(f.request,PATIENT);assertEquals(amount,output.get("balanceMinor"));assertInstanceOf(Long.class,output.get("balanceMinor"));assertEquals("PEN",output.get("currency"));}assertEquals(5,f.args.size());}
 @Test void exactResultsetsAndOneRowAreRequiredNoFakeZero(){for(var result:List.of(new SqlServerExecutor.Result(List.of(),List.of()),new SqlServerExecutor.Result(List.of(List.of()),List.of()),new SqlServerExecutor.Result(List.of(List.of(Map.of("balanceMinor",0L,"currency","PEN")),List.of()),List.of()),new SqlServerExecutor.Result(List.of(List.of(Map.of("balanceMinor",0L,"currency","PEN"),Map.of("balanceMinor",1L,"currency","PEN"))),List.of()))){f.results.add(result);safe(()->f.store.balance(f.request,PATIENT));assertEquals("rollback",f.manager.events.getLast());}}
 @Test void missingNullAndCoercedNumberCurrencyAreRejected(){for(String key:List.of("balanceMinor","currency")){var row=new LinkedHashMap<String,Object>(Map.of("balanceMinor",0L,"currency","PEN"));row.remove(key);f.results.add(result(row));safe(()->f.store.balance(f.request,PATIENT));row.put(key,null);f.results.add(result(row));safe(()->f.store.balance(f.request,PATIENT));}for(Object value:List.of(0,0.0,"0",new java.math.BigInteger("0"),new java.math.BigDecimal("0"),false)){f.results.add(result(Map.of("balanceMinor",value,"currency","PEN")));safe(()->f.store.balance(f.request,PATIENT));}for(Object value:List.of("USD","pen","PEN ","",3)){f.results.add(result(Map.of("balanceMinor",0L,"currency",value)));safe(()->f.store.balance(f.request,PATIENT));}}
 @Test void invalidIdsNeverExecuteAndRolePortalFinanceGatesMatchContract(){for(String id:Arrays.asList(null,"bad",PATIENT.toUpperCase()))assertEquals(400,assertThrows(ApiException.class,()->f.store.balance(f.request,id)).status);for(String role:List.of("ADM","REC","PRO","ASI","AUD","SAD","SOP")){f.actor(role);assertEquals(403,assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT)).status);}f.actor("PAC");for(List<String> modules:List.of(List.<String>of(),List.of("PORTAL"),List.of("FINANCE"))){f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",modules));assertEquals("MODULE_NOT_INCLUDED",assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT)).code);}verifyNoInteractions(f.executor);}
 @Test void pacResRetainReadsForSuspendedTenantWithoutCoreGate(){for(String role:List.of("PAC","RES")){f.actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of("PORTAL","FINANCE")));assertEquals(0L,f.store.balance(f.request,PATIENT).get("balanceMinor"));}}
 @Test void malformedRequestActorHostUuidAndTokenFailBeforeExecutor(){safe(()->f.store.balance(null,PATIENT));f.request.setAttribute("health.tenant","bad");safe(()->f.store.balance(f.request,PATIENT));f.actor("PAC");f.request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT)).status);f.actor("PAC");f.request.setAttribute("health.actor",new Actor("bad","Synthetic","synthetic@example.test",TENANT,List.of("PAC"),"a".repeat(64)));safe(()->f.store.balance(f.request,PATIENT));f.request.setAttribute("health.actor",new Actor(ACTOR,"Synthetic","synthetic@example.test",TENANT,List.of("PAC"),"bad"));safe(()->f.store.balance(f.request,PATIENT));f.actor("PAC");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("PORTAL","FINANCE")));assertEquals(403,assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT)).status);verifyNoInteractions(f.executor);}
 @Test void vendorLinkPermissionAndInfrastructureErrorsDoNotRetryOrLeak(){for(int vendor:List.of(51001,51002,51003,99999)){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,vendor))).when(f.executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,()->f.store.balance(f.request,PATIENT));assertEquals(vendor==51001?403:vendor==51002?404:vendor==51003?409:500,e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}verify(f.executor,times(4)).execute(eq(SqlServerProcedure.PORTAL_BALANCE),any(),eq(PATIENT));}
 @Test void requiredJoinCancelAndCommitFailureRemainSafe(){assertThrows(RuntimeException.class,()->f.manager.outer(()->{f.store.balance(f.request,PATIENT);assertFalse(f.manager.events.contains("commit"));throw new RuntimeException("cancel");}));assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals("rollback",f.manager.events.getLast());f.manager.failCommit=true;safe(()->f.store.balance(f.request,PATIENT));assertEquals(2,f.args.size());assertEquals("SqlServerPortalBalanceStore[redacted]",f.store.toString());}
}
